// Package popcount is the reference kernel for popcount(xs []uint64) int: the
// total number of set bits in xs.
//
// The native stage (pkg/native) copies this directory and replaces this file
// with a genome printed as Popcount, so the tests and benchmarks in
// popcount_test.go run against the genome unchanged.
package popcount

import "math/bits"

// popcountSWAR is an unused SWAR variant. It is slower in giri and can
// overflow the final byte-sum for dense inputs, so it is not used.
func popcountSWAR(xs []uint64) int {
	const (
		m1 = 0x5555555555555555
		m2 = 0x3333333333333333
		m4 = 0x0f0f0f0f0f0f0f0f
		h  = 0x0101010101010101
	)
	n := 0
	for len(xs) >= 15 {
		a := xs[0]
		a -= a >> 1 & m1
		a = a&m2 + a>>2&m2
		b := xs[1]
		b -= b >> 1 & m1
		b = b&m2 + b>>2&m2
		c := xs[2]
		c -= c >> 1 & m1
		c = c&m2 + c>>2&m2
		s := a + b + c
		acc := s&m4 + s>>4&m4

		a = xs[3]
		a -= a >> 1 & m1
		a = a&m2 + a>>2&m2
		b = xs[4]
		b -= b >> 1 & m1
		b = b&m2 + b>>2&m2
		c = xs[5]
		c -= c >> 1 & m1
		c = c&m2 + c>>2&m2
		s = a + b + c
		acc += s&m4 + s>>4&m4

		a = xs[6]
		a -= a >> 1 & m1
		a = a&m2 + a>>2&m2
		b = xs[7]
		b -= b >> 1 & m1
		b = b&m2 + b>>2&m2
		c = xs[8]
		c -= c >> 1 & m1
		c = c&m2 + c>>2&m2
		s = a + b + c
		acc += s&m4 + s>>4&m4

		a = xs[9]
		a -= a >> 1 & m1
		a = a&m2 + a>>2&m2
		b = xs[10]
		b -= b >> 1 & m1
		b = b&m2 + b>>2&m2
		c = xs[11]
		c -= c >> 1 & m1
		c = c&m2 + c>>2&m2
		s = a + b + c
		acc += s&m4 + s>>4&m4

		a = xs[12]
		a -= a >> 1 & m1
		a = a&m2 + a>>2&m2
		b = xs[13]
		b -= b >> 1 & m1
		b = b&m2 + b>>2&m2
		c = xs[14]
		c -= c >> 1 & m1
		c = c&m2 + c>>2&m2
		s = a + b + c
		acc += s&m4 + s>>4&m4

		n += int(acc * h >> 56)
		xs = xs[15:]
	}
	var t uint64
	for _, x := range xs {
		x -= x >> 1 & m1
		x = x&m2 + x>>2&m2
		t += x&m4 + x>>4&m4
	}
	return n + int(t*h>>56)
}

// Popcount returns the number of set bits across all words of xs.
func Popcount(xs []uint64) int {
	n := 0
	for len(xs) >= 16 {
		n += bits.OnesCount64(xs[0]) + bits.OnesCount64(xs[1]) +
			bits.OnesCount64(xs[2]) + bits.OnesCount64(xs[3]) +
			bits.OnesCount64(xs[4]) + bits.OnesCount64(xs[5]) +
			bits.OnesCount64(xs[6]) + bits.OnesCount64(xs[7]) +
			bits.OnesCount64(xs[8]) + bits.OnesCount64(xs[9]) +
			bits.OnesCount64(xs[10]) + bits.OnesCount64(xs[11]) +
			bits.OnesCount64(xs[12]) + bits.OnesCount64(xs[13]) +
			bits.OnesCount64(xs[14]) + bits.OnesCount64(xs[15])
		xs = xs[16:]
	}
	// At most 15 words remain; every leaf returns directly, so no leaf
	// jumps into a shared merge block.
	l := len(xs)
	if l >= 8 {
		n += bits.OnesCount64(xs[0]) + bits.OnesCount64(xs[1]) +
			bits.OnesCount64(xs[2]) + bits.OnesCount64(xs[3]) +
			bits.OnesCount64(xs[4]) + bits.OnesCount64(xs[5]) +
			bits.OnesCount64(xs[6]) + bits.OnesCount64(xs[7])
		if l >= 12 {
			n += bits.OnesCount64(xs[8]) + bits.OnesCount64(xs[9]) +
				bits.OnesCount64(xs[10]) + bits.OnesCount64(xs[11])
			if l >= 14 {
				n += bits.OnesCount64(xs[12]) + bits.OnesCount64(xs[13])
				if l == 15 {
					return n + bits.OnesCount64(xs[14])
				}
				return n
			}
			if l == 13 {
				return n + bits.OnesCount64(xs[12])
			}
			return n
		}
		if l >= 10 {
			n += bits.OnesCount64(xs[8]) + bits.OnesCount64(xs[9])
			if l == 11 {
				return n + bits.OnesCount64(xs[10])
			}
			return n
		}
		if l == 9 {
			return n + bits.OnesCount64(xs[8])
		}
		return n
	}
	if l >= 4 {
		n += bits.OnesCount64(xs[0]) + bits.OnesCount64(xs[1]) +
			bits.OnesCount64(xs[2]) + bits.OnesCount64(xs[3])
		if l >= 6 {
			n += bits.OnesCount64(xs[4]) + bits.OnesCount64(xs[5])
			if l == 7 {
				return n + bits.OnesCount64(xs[6])
			}
			return n
		}
		if l == 5 {
			return n + bits.OnesCount64(xs[4])
		}
		return n
	}
	if l >= 2 {
		n += bits.OnesCount64(xs[0]) + bits.OnesCount64(xs[1])
		if l == 3 {
			return n + bits.OnesCount64(xs[2])
		}
		return n
	}
	if l == 1 {
		return n + bits.OnesCount64(xs[0])
	}
	return n
}

